import React, { useState, useEffect } from 'react';
import { Camera, Check, Film, Music, Plus, Settings, Users, Clock, Edit, XCircle, Trash2 } from 'lucide-react';
import { fetchTasks, fetchNotes, fetchMilestones, fetchSystemStatus, addNote as apiAddNote, updateNote, updateTask, updateMilestone } from './api';
import ShotList from './components/ShotList';
import ProductionTimeline from './components/ProductionTimeline';
import TasksPage from './components/TasksPage';
import ConceptBoard from './components/ConceptBoard';

// Updated color scheme based on your preferences
const colors = {
  primary: '#ff3d7f',       // Vibrant pink
  primaryLight: '#ff9db8',  // Lighter pink
  primaryDark: '#9c6172',   // Darker pink
  secondary: '#121212',     // Deeper black
  secondaryLight: '#212121',// Light black
  light: '#ffffff',         // White
  midGray: '#868686',       // Mid gray
  accent: '#00dbdd',        // Teal accent (cyan blue)
  successGreen: '#4ADE80',  // Green for completed items
  warningOrange: '#dc6300', // Orange for warnings
  errorRed: '#FF3D3D'       // Red for errors/delete
};

// Piano key configuration - made wider
const pianoKeys = [
  { id: 'overview', label: 'Overview', isBlack: false },
  { id: 'timeline', label: 'Timeline', isBlack: true },
  { id: 'tasks', label: 'Tasks', isBlack: false },
  { id: 'shots', label: 'Shots', isBlack: true },
  { id: 'concepts', label: 'Concepts', isBlack: false },
  { id: 'notes', label: 'Notes', isBlack: true },
];

function App() {
  const [activeTab, setActiveTab] = useState('overview');
  
  // Initialize tasks from localStorage or as empty array
  const [tasks, setTasks] = useState(() => {
    const savedTasks = localStorage.getItem('melodicJustice_tasks');
    return savedTasks ? JSON.parse(savedTasks) : [];
  });
  
  // Initialize notes from localStorage or as empty array
  const [notes, setNotes] = useState(() => {
    const savedNotes = localStorage.getItem('melodicJustice_notes');
    return savedNotes ? JSON.parse(savedNotes) : [];
  });
  
  const [milestones, setMilestones] = useState(() => {
    const savedMilestones = localStorage.getItem('melodicJustice_milestones');
    return savedMilestones ? JSON.parse(savedMilestones) : [
      { id: 1, name: 'Pre-Production', completed: false, active: true, description: 'Character design, storyboarding, and initial setup', targetDate: '2025-06-01', order: 1 },
      { id: 2, name: 'Production', completed: false, active: false, description: 'Animation, modeling, and scene assembly', targetDate: '2025-09-01', order: 2 },
      { id: 3, name: 'Post-Production', completed: false, active: false, description: 'Rendering, effects, music, and final touches', targetDate: '2025-12-01', order: 3 }
    ];
  });

  // Initialize systemStatus with default values to prevent undefined errors
  const [systemStatus, setSystemStatus] = useState({
    storage: { total: 0, used: 0, percentage: 0 },
    backup: { last_backup: new Date().toISOString(), status: 'OK' },
    render_cache: { total: 0, used: 0, percentage: 0 }
  });

  // UI state
  const [newNote, setNewNote] = useState('');
  const [editingStatCard, setEditingStatCard] = useState(null);
  const [showAddNoteModal, setShowAddNoteModal] = useState(false);
  
  // Piano key sound effect state
  const [keySound, setKeySound] = useState(null);
  
  // Initialize project stats from localStorage or with defaults
  const [projectStats, setProjectStats] = useState(() => {
    const savedStats = localStorage.getItem('melodicJustice_projectStats');
    return savedStats ? JSON.parse(savedStats) : {
      scenes: { total: 24, completed: 0, label: 'Scenes Completed', iconType: 'film' },
      characters: { total: 6, completed: 0, label: 'Characters Rigged', iconType: 'users' },
      shots: { total: 300, completed: 0, label: 'Shots Animated', iconType: 'camera' },
      music: { total: 8, completed: 0, label: 'Music Tracks', iconType: 'music' }
    };
  });

  // Initialize audio for piano key sounds
  useEffect(() => {
    // Create audio context for piano key sounds
    const audioContext = new (window.AudioContext || window.webkitAudioContext)();
    
    // Define piano key frequencies (C4 to A4)
    const frequencies = [261.63, 277.18, 293.66, 311.13, 329.63, 349.23];
    
    setKeySound(() => {
      // Return a function that plays a piano note when called
      return (index) => {
        const oscillator = audioContext.createOscillator();
        const gainNode = audioContext.createGain();
        
        oscillator.type = 'sine';
        oscillator.frequency.value = frequencies[index % frequencies.length];
        
        gainNode.gain.value = 0.1;
        gainNode.gain.exponentialRampToValueAtTime(0.001, audioContext.currentTime + 0.5);
        
        oscillator.connect(gainNode);
        gainNode.connect(audioContext.destination);
        
        oscillator.start();
        oscillator.stop(audioContext.currentTime + 0.5);
      };
    });
    
    return () => {
      // Cleanup
      if (audioContext && audioContext.state !== 'closed') {
        audioContext.close();
      }
    };
  }, []);
  
  const getIcon = (iconType) => {
    switch(iconType) {
      case 'film': return <Film className="w-6 h-6" />;
      case 'users': return <Users className="w-6 h-6" />;
      case 'camera': return <Camera className="w-6 h-6" />;
      case 'music': return <Music className="w-6 h-6" />;
      default: return null;
    }
  };
  
  // Save data to localStorage when it changes
  useEffect(() => {
    localStorage.setItem('melodicJustice_tasks', JSON.stringify(tasks));
  }, [tasks]);
  
  useEffect(() => {
    localStorage.setItem('melodicJustice_notes', JSON.stringify(notes));
  }, [notes]);
  
  useEffect(() => {
    localStorage.setItem('melodicJustice_milestones', JSON.stringify(milestones));
  }, [milestones]);
  
  useEffect(() => {
    localStorage.setItem('melodicJustice_projectStats', JSON.stringify(projectStats));
  }, [projectStats]);
  
  // Load data from API if available
  useEffect(() => {
    const loadData = async () => {
      try {
        const fetchedTasks = await fetchTasks();
        if (fetchedTasks && fetchedTasks.length > 0) setTasks(fetchedTasks);
        
        const fetchedNotes = await fetchNotes();
        if (fetchedNotes && fetchedNotes.length > 0) setNotes(fetchedNotes);
        
        const fetchedMilestones = await fetchMilestones();
        if (fetchedMilestones && fetchedMilestones.length > 0) setMilestones(fetchedMilestones);
        
        const status = await fetchSystemStatus();
        if (status) {
          setSystemStatus(status);
        }
      } catch (error) {
        console.error("Error loading data from API, using localStorage instead:", error);
      }
    };
    
    // Try to load from API, but don't worry if it fails - we'll use localStorage
    loadData();
  }, []);

  // Function to check if milestone should advance
  const checkMilestoneAdvancement = (updatedTasks) => {
    const activeMilestone = milestones.find(m => m.active);
    if (!activeMilestone) return;
    
    const milestoneTasks = updatedTasks.filter(task => task.milestone === activeMilestone.name);
    const allTasksComplete = milestoneTasks.length > 0 && milestoneTasks.every(task => task.completed);
    
    if (allTasksComplete) {
      // Find the next milestone to advance to
      const currentIndex = milestones.findIndex(m => m.id === activeMilestone.id);
      const nextIndex = currentIndex + 1;
      
      // If there's a next milestone, make it active
      if (nextIndex < milestones.length) {
        const nextMilestoneId = milestones[nextIndex].id;
        toggleMilestone(nextMilestoneId);
      }
    }
  };
  
  // Handler functions
  const addNoteHandler = async () => {
    if (newNote.trim() !== '') {
      try {
        const noteData = { 
          id: notes.length > 0 ? Math.max(...notes.map(n => n.id)) + 1 : 1,
          text: newNote, 
          completed: false,
          createdAt: new Date().toISOString()
        };
        
        // Try API first
        try {
          const savedNote = await apiAddNote(noteData);
          setNotes([...notes, savedNote]);
        } catch (apiError) {
          // Fall back to localStorage if API fails
          setNotes([...notes, noteData]);
        }
        
        setNewNote('');
        setShowAddNoteModal(false);
      } catch (error) {
        // Final fallback
        const noteData = { 
          id: notes.length > 0 ? Math.max(...notes.map(n => n.id)) + 1 : 1,
          text: newNote, 
          completed: false,
          createdAt: new Date().toISOString()
        };
        setNotes([...notes, noteData]);
        setNewNote('');
        setShowAddNoteModal(false);
        console.error("Failed to add note to API, using localStorage instead");
      }
    }
  };
  
  const toggleNoteComplete = async (id) => {
    try {
      const note = notes.find(n => n.id === id);
      const updatedNote = { ...note, completed: !note.completed };
      
      // Try API first
      try {
        await updateNote(id, updatedNote);
      } catch (apiError) {
        // API not available, that's okay
      }
      
      // Update local state regardless
      setNotes(notes.map(note => 
        note.id === id ? updatedNote : note
      ));
    } catch (error) {
      console.error("Failed to update note:", error);
    }
  };
  
  const deleteNote = async (id) => {
    try {
      // Remove from local state first for instant feedback
      setNotes(notes.filter(note => note.id !== id));
      
      // Then try to remove from backend
      try {
        // await apiDeleteNote(id);
      } catch (apiError) {
        // API not available, that's okay
      }
    } catch (error) {
      console.error("Failed to delete note:", error);
    }
  };
  
  const toggleMilestone = async (id) => {
    try {
      // Try API first
      try {
        await updateMilestone(id);
      } catch (apiError) {
        // API not available, that's okay
      }
      
      // Update local state regardless
      setMilestones(milestones.map(milestone => 
        milestone.id === id ? { ...milestone, active: true } : { ...milestone, active: false }
      ));
    } catch (error) {
      console.error("Failed to update milestone:", error);
    }
  };
  
  const toggleTaskComplete = async (id) => {
    try {
      const task = tasks.find(t => t.id === id);
      const updatedTask = { ...task, completed: !task.completed };
      
      // Update local state immediately for responsive UI
      const updatedTasks = tasks.map(task => 
        task.id === id ? updatedTask : task
      );
      setTasks(updatedTasks);
      
      // Check if we should advance to the next milestone
      checkMilestoneAdvancement(updatedTasks);
      
      // Try to update server state
      try {
        await updateTask(id, updatedTask);
      } catch (apiError) {
        // API not available, that's okay
      }
    } catch (error) {
      console.error("Failed to update task:", error);
    }
  };

  // Function to handle piano key click
  const handlePianoKeyClick = (key, index) => {
    setActiveTab(key.id);
    
    // Play sound if keySound is available
    if (keySound) {
      keySound(index);
    }
  };

  // New function to handle stat card editing
  const updateStatCard = (key, updates) => {
    setProjectStats(prev => ({
      ...prev,
      [key]: {
        ...prev[key],
        ...updates
      }
    }));
    setEditingStatCard(null);
  };

  // Add new task function
  const addTask = async (taskData) => {
    try {
      // Generate a new ID
      const newId = tasks.length > 0 ? Math.max(...tasks.map(t => t.id)) + 1 : 1;
      const newTask = { 
        ...taskData, 
        id: newId,
        createdAt: new Date().toISOString()
      };
      
      // Update local state
      const updatedTasks = [...tasks, newTask];
      setTasks(updatedTasks);
      
      // Try API if needed
      try {
        // await apiAddTask(newTask);
      } catch (apiError) {
        // API not available, that's okay
      }
      
      return newTask;
    } catch (error) {
      console.error("Failed to add task:", error);
      return null;
    }
  };

  // Delete task function
  const deleteTask = async (id) => {
    try {
      // Update local state
      setTasks(tasks.filter(task => task.id !== id));
      
      // Try API if needed
      try {
        // await apiDeleteTask(id);
      } catch (apiError) {
        // API not available, that's okay
      }
    } catch (error) {
      console.error("Failed to delete task:", error);
    }
  };

  // Filter tasks based on active milestone
  const activeMilestoneName = milestones.find(m => m.active)?.name || 'Pre-Production';
  const filteredTasks = tasks.filter(task => task.milestone === activeMilestoneName);

  // Calculate overall project progress for timeline
  const calculateProgress = () => {
    if (tasks.length === 0) return 0;
    
    const completedTasks = tasks.filter(task => task.completed).length;
    return Math.round((completedTasks / tasks.length) * 100);
  };

  // Format storage size for display
  const formatBytes = (bytes, decimals = 2) => {
    if (bytes === 0 || bytes === undefined) return '0 Bytes';
    
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    
    return parseFloat((bytes / Math.pow(k, i)).toFixed(decimals)) + ' ' + sizes[i];
  };

  return (
    <div className="min-h-screen flex flex-col" style={{ backgroundColor: '#d2b48c' }}>
      {/* Pink header */}
      <div className="w-full py-4 border-b-4 border-pink-400" style={{ backgroundColor: colors.primary }}>
        <div className="max-w-6xl mx-auto px-4 flex justify-between items-center">
          <div className="flex items-center gap-4">
            <img 
              src="/logo192.png" 
              alt="Melodic Justice Logo"
              className="h-16 w-auto mr-3 hover-scale drop-shadow-lg"
            />
            <div>
              <h1 className="text-white text-2xl font-bold drop-shadow-md">MELODIC JUSTICE</h1>
              <p className="text-pink-100 text-sm drop-shadow-sm">Animation Pipeline Dashboard</p>
            </div>
          </div>
          <div className="text-white flex flex-col items-end">
            <div className="flex items-center gap-2 bg-white bg-opacity-10 px-4 py-2 rounded-full">
              <Clock className="mr-1 w-4 h-4" />
              <span className="font-medium">{new Date().toLocaleDateString()}</span>
            </div>
            <div className="text-sm text-pink-100 opacity-70 mt-1">
              Started: July 25, 2023
            </div>
          </div>
        </div>
      </div>
      
      <div className="max-w-6xl mx-auto px-4 py-6 flex-grow">
        {/* Piano Key Navigation - Made wider and more stylish */}
        <div className="mb-8 relative overflow-hidden fade-in">
          <div className="flex justify-center gap-1">
            {pianoKeys.map((key, index) => (
              <div 
                key={key.id} 
                className={`relative ${index > 0 ? '' : ''}`}
              >
                <button
                  onClick={() => handlePianoKeyClick(key, index)}
                  className={`
                    border-2 border-gray-500 rounded-b-lg shadow-lg transition-all duration-300 
                    ${key.isBlack 
                      ? 'bg-gray-900 text-white z-10 h-20 relative transform' 
                      : 'bg-white text-gray-900 z-0 h-32'
                    }
                    ${activeTab === key.id 
                      ? key.isBlack 
                        ? 'bg-purple-900 border-purple-600 scale-105' 
                        : 'bg-pink-50 border-pink-400 scale-105' 
                      : ''
                    }
                    hover:shadow-xl hover:scale-105 transform transition-all
                  `}
                  style={{
                    width: key.isBlack ? '9rem' : '12rem',
                    marginLeft: key.isBlack ? '-4.5rem' : '0',
                    marginRight: key.isBlack ? '-4.5rem' : '0',
                    boxShadow: activeTab === key.id 
                      ? key.isBlack 
                        ? '0 0 30px rgba(168, 85, 247, 0.7)' 
                        : '0 0 30px rgba(255, 61, 127, 0.5)' 
                      : '0 4px 6px rgba(0,0,0,0.1)'
                  }}
                >
                  <div className={`absolute ${key.isBlack ? 'bottom-3' : 'bottom-6'} w-full text-center text-sm font-bold`}>
                    {key.label}
                  </div>
                </button>
              </div>
            ))}
          </div>
        </div>

        {/* Timeline Tab */}
        {activeTab === 'timeline' && (
          <div className="rounded-lg p-6 tab-content fade-in" style={{ backgroundColor: colors.secondary }}>
            <div className="mb-8">
              <h2 className="text-2xl font-bold text-white mb-2">Production Timeline</h2>
              <p className="text-gray-400">Track your project's progress through major production phases</p>
            </div>
            
            {/* Main timeline component */}
            <ProductionTimeline milestones={milestones} tasks={tasks} />
            
            {/* Add task lists for each milestone category below */}
            <div className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-6">
              {milestones.map(milestone => (
                <div 
                  key={milestone.id}
                  className="bg-gray-800 rounded-lg overflow-hidden hover-glow transition-all slide-in-right shadow-lg"
                >
                  <div 
                    className="p-4 border-b border-gray-700 flex justify-between items-center"
                    style={{ 
                      backgroundColor: milestone.active 
                        ? 'rgba(255, 61, 127, 0.2)' 
                        : 'rgba(30, 20, 30, 0.3)' 
                    }}
                  >
                    <h3 className="text-lg font-bold text-white">{milestone.name}</h3>
                    <button 
                      className="p-2 rounded bg-pink-600 hover:bg-pink-700 hover-scale transition-all"
                      onClick={() => {
                        setActiveTab('tasks');
                      }}
                    >
                      <Plus className="h-4 w-4 text-white" />
                    </button>
                  </div>
                  
                  <div className="p-4">
                    {/* Show tasks for this milestone */}
                    <div className="space-y-2">
                      {tasks
                        .filter(task => task.milestone === milestone.name)
                        .map(task => (
                          <div 
                            key={task.id}
                            className="flex items-center p-3 rounded bg-gray-900 hover-glow transition-all"
                          >
                            <div 
                              className="cursor-pointer mr-3 flex-shrink-0 transition-all"
                              onClick={() => toggleTaskComplete(task.id)}
                            >
                              {task.completed ? 
                                <div className="h-5 w-5 rounded-full bg-green-500 flex items-center justify-center transition-all">
                                  <Check className="h-3 w-3 text-white" />
                                </div> : 
                                <div className="h-5 w-5 rounded-full border border-gray-500 hover:border-white transition-all" />
                              }
                            </div>
                            <div className={task.completed ? 'text-gray-400 line-through' : 'text-white'}>
                              {task.name}
                            </div>
                          </div>
                        ))}
                      
                      {tasks.filter(task => task.milestone === milestone.name).length === 0 && (
                        <div className="text-center text-gray-500 py-4">
                          No tasks yet
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Overview Tab */}
        {activeTab === 'overview' && (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
              {Object.entries(projectStats).map(([key, stat]) => (
                <div 
                  key={key} 
                  className="rounded-lg p-6 hover-glow transition-all fade-in cursor-pointer shadow-lg hover:shadow-xl"
                  style={{ backgroundColor: '#1a1a1a' }}
                  onClick={() => {
                    // Link each stat card to the appropriate tab
                    if (key === 'scenes' || key === 'shots') {
                      setActiveTab('shots');
                    } else if (key === 'characters') {
                      setActiveTab('concepts');
                    } else if (key === 'music') {
                      setActiveTab('notes');
                    }
                  }}
                >
                  <div className="flex items-center justify-between pb-3">
                    <span className="text-base font-medium text-gray-400">{stat.label}</span>
                    <div className="flex space-x-3 items-center">
                      <div className="text-pink-400">
                        {getIcon(stat.iconType)}
                      </div>
                      <button 
                        className="p-1 rounded-full hover:bg-gray-800 transition-all"
                        onClick={(e) => {
                          e.stopPropagation();
                          setEditingStatCard(key);
                        }}
                      >
                        <Edit className="h-4 w-4 text-gray-400 hover:text-white" />
                      </button>
                    </div>
                  </div>
                  <div className="text-3xl font-bold text-white mb-3">
                    {stat.completed}/{stat.total}
                  </div>
                  <div className="w-full bg-gray-700 h-3 rounded-full overflow-hidden">
                    <div 
                      className="h-full rounded-full animate-progress transition-all duration-1000"
                      style={{ 
                        width: `${(stat.completed / stat.total) * 100}%`,
                        backgroundColor: colors.accent
                      }}
                    ></div>
                  </div>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
              <div className="lg:col-span-2 rounded-lg p-6 fade-in shadow-lg" style={{ backgroundColor: '#1a1a1a' }}>
                <div className="mb-6">
                  <h2 className="text-2xl font-bold text-white mb-6">Active Milestone: {activeMilestoneName}</h2>
                  
                  <div className="flex space-x-2 overflow-x-auto py-4 mb-6">
                    
                  </div>

                  <div className="relative h-10 bg-gray-700 rounded-full mb-8 overflow-hidden shadow-inner">
                    {milestones.sort((a, b) => a.order - b.order).map((milestone, index) => {
                      // Calculate position based on order
                      const totalMilestones = milestones.length;
                      const position = (index / totalMilestones) * 100;
                      const nextPosition = ((index + 1) / totalMilestones) * 100;
                      const width = nextPosition - position;
                      
                      return (
                        <div 
                          key={milestone.id}
                          className="absolute top-0 h-full flex items-center justify-center text-sm font-medium text-white px-3 transition-all"
                          style={{ 
                            left: `${position}%`, 
                            width: `${width}%`,
                            backgroundColor: milestone.completed 
                              ? colors.successGreen 
                              : milestone.active 
                                ? colors.primary
                                : 'rgba(75, 75, 75, 0.5)',
                            borderRight: index < totalMilestones - 1 ? '1px solid rgba(255,255,255,0.2)' : 'none'
                          }}
                        >
                          <span className="truncate">{milestone.name}</span>
                        </div>
                      );
                    })}
                    
                    {/* Current progress indicator */}
                    <div 
                      className="absolute top-0 h-full w-1 bg-white you-are-here"
                      style={{ 
                        left: `${calculateProgress()}%`,
                        boxShadow: '0 0 15px rgba(255,255,255,0.8)'
                      }}
                    ></div>
                  </div>
                </div>
                
                <h3 className="text-lg font-medium text-white mb-4 border-b border-gray-800 pb-2">Current Tasks</h3>
                <div className="space-y-3">
                  {filteredTasks.length > 0 ? (
                    filteredTasks.map(task => (
                      <div key={task.id} className="p-4 rounded-lg bg-gray-800 flex items-start hover-glow transition-all shadow">
                        <div 
                          className="cursor-pointer mr-3 mt-1 flex-shrink-0 transition-all"
                          onClick={() => toggleTaskComplete(task.id)}
                        >
                          {task.completed ? 
                            <div className="h-6 w-6 rounded-full bg-green-500 flex items-center justify-center transition-all">
                              <Check className="h-4 w-4 text-white" />
                            </div> : 
                            <div className="h-6 w-6 rounded-full border-2 border-gray-500 hover:border-white transition-all" />
                          }
                        </div>
                        <div className="flex-grow">
                          <div className="flex justify-between items-center mb-2">
                            <div>
                              <h3 className={`font-medium ${task.completed ? 'text-gray-400 line-through' : 'text-white'}`}>
                                {task.name}
                              </h3>
                              {task.category && (
                                <span className="text-sm text-gray-400">{task.category}</span>
                              )}
                            </div>
                            {task.progress !== undefined && (
                              <span className="text-sm text-gray-400">{task.progress}%</span>
                            )}
                          </div>
                          {task.progress !== undefined && (
                            <div className="w-full bg-gray-700 h-2 rounded-full">
                              <div 
                                className="h-full rounded-full animate-progress"
                                style={{ 
                                  width: `${task.progress}%`,
                                  backgroundColor: task.completed ? colors.successGreen : colors.accent 
                                }}
                              ></div>
                            </div>
                          )}
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="p-6 rounded-lg bg-gray-800 text-gray-400 text-center">
                      No tasks for this milestone yet
                    </div>
                  )}
                </div>
              </div>

              <div className="rounded-lg p-6 fade-in shadow-lg" style={{ backgroundColor: '#1a1a1a' }}>
                <div className="flex items-center justify-between mb-6">
                  <h2 className="text-xl font-bold text-white">Quick Notes</h2>
                  <button
                    className="px-4 py-2 rounded-lg flex items-center text-white hover-scale transition-all shadow"
                    style={{ backgroundColor: colors.accent }}
                    onClick={() => setShowAddNoteModal(true)}
                  >
                    <Plus className="h-4 w-4 mr-1" />
                    <span>Add</span>
                  </button>
                </div>
                <div className="space-y-3 mb-6 max-h-72 overflow-y-auto custom-scrollbar">
                  {notes.length === 0 ? (
                    <div className="text-center text-gray-500 py-6">
                      No notes yet. Add some!
                    </div>
                  ) : (
                    notes.slice(0, 10).map(note => (
                      <div 
                        key={note.id} 
                        className="flex items-start p-3 rounded-lg hover-glow transition-all"
                        style={{ backgroundColor: note.completed ? '#2a2a2a' : '#212121' }}
                      >
                        <div 
                          className="cursor-pointer mr-3 mt-1 transition-all"
                          onClick={() => toggleNoteComplete(note.id)}
                        >
                          {note.completed ? 
                            <div className="h-5 w-5 rounded-full bg-green-500 flex items-center justify-center transition-all">
                              <Check className="h-3 w-3 text-white" />
                            </div> : 
                            <div className="h-5 w-5 rounded-full border border-gray-500 hover:border-white transition-all" />
                          }
                        </div>
                        <p className={`text-sm flex-grow ${note.completed ? 'text-gray-400 line-through' : 'text-gray-300'}`}>
                          {note.text}
                        </p>
                        <button 
                          className="p-1 rounded-full hover:bg-gray-700 transition-all ml-2"
                          onClick={() => deleteNote(note.id)}
                        >
                          <Trash2 className="h-3 w-3 text-gray-500 hover:text-red-400" />
                        </button>
                      </div>
                    ))
                  )}
                </div>
                <button 
                  onClick={() => setActiveTab('notes')}
                  className="w-full py-3 mt-2 text-center text-gray-400 hover:text-white rounded-lg border border-gray-700 hover:border-pink-500 transition-all hover:bg-gray-800"
                >
                  View All Notes
                </button>
              </div>
            </div>

            <div className="rounded-lg p-6 fade-in shadow-lg" style={{ backgroundColor: '#1a1a1a' }}>
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-xl font-bold text-white">System Status</h2>
                <Settings className="w-5 h-5 text-gray-400 hover:text-white hover-scale transition-all cursor-pointer" />
              </div>
              
              {/* Simplified production system status */}
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
                <div className="bg-gray-800 rounded-lg p-4 hover-glow transition-all">
                  <div className="flex justify-between items-center">
                    <h3 className="text-white font-medium">Storage</h3>
                    <div className="h-3 w-3 bg-green-500 rounded-full pulse" />
                  </div>
                  <p className="text-sm text-gray-400 mt-1">
                    {systemStatus?.storage?.used !== undefined ? 
                      `${formatBytes(systemStatus.storage.used)} / ${formatBytes(systemStatus.storage.total)}` : 
                      "Not connected"}
                  </p>
                  <div className="w-full bg-gray-700 h-2 rounded-full mt-2">
                    <div 
                      className="h-full rounded-full animate-progress"
                      style={{ 
                        width: `${systemStatus?.storage?.percentage || 0}%`,
                        backgroundColor: colors.accent 
                      }}
                    ></div>
                  </div>
                </div>
                
                <div className="bg-gray-800 rounded-lg p-4 hover-glow transition-all">
                  <div className="flex justify-between items-center">
                    <h3 className="text-white font-medium">Backup</h3>
                    <div className="h-3 w-3 bg-green-500 rounded-full pulse" />
                  </div>
                  <p className="text-sm text-gray-400 mt-1">
                    {systemStatus?.backup?.last_backup ? 
                      `Last: ${new Date(systemStatus.backup.last_backup).toLocaleDateString()}` : 
                      "Not configured"}
                  </p>
                </div>
                
                <div className="bg-gray-800 rounded-lg p-4 hover-glow transition-all">
                  <div className="flex justify-between items-center">
                    <h3 className="text-white font-medium">Render Cache</h3>
                    <div className="h-3 w-3 bg-green-500 rounded-full pulse" />
                  </div>
                  <p className="text-sm text-gray-400 mt-1">
                    {systemStatus?.render_cache?.used !== undefined ? 
                      `${formatBytes(systemStatus.render_cache.used)} / ${formatBytes(systemStatus.render_cache.total)}` : 
                      "Not connected"}
                  </p>
                  <div className="w-full bg-gray-700 h-2 rounded-full mt-2">
                    <div 
                      className="h-full rounded-full animate-progress"
                      style={{ 
                        width: `${systemStatus?.render_cache?.percentage || 0}%`,
                        backgroundColor: colors.accent 
                      }}
                    ></div>
                  </div>
                </div>
                
                <div className="bg-gray-800 rounded-lg p-4 hover-glow transition-all">
                  <div className="flex justify-between items-center">
                    <h3 className="text-white font-medium">Blender Pipeline</h3>
                    <div className="h-3 w-3 bg-green-500 rounded-full pulse" />
                  </div>
                  <p className="text-sm text-gray-400 mt-1">
                    Connected & Ready
                  </p>
                </div>
              </div>
              
              {/* Simplified Software Status */}
              <div className="bg-gray-800 rounded-lg p-4">
                <h3 className="text-lg font-medium text-white mb-4">Production Software Status</h3>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  {[
                    { name: 'Blender', status: 'connected' },
                    { name: 'Rokoko', status: 'warning' },
                    { name: 'Server', status: 'connected' },
                    { name: 'Storage', status: 'connected' }
                  ].map((software) => (
                    <div key={software.name} className="flex items-center justify-between bg-gray-700 rounded p-3">
                      <span className="text-white">{software.name}</span>
                      <div 
                        className="h-3 w-3 rounded-full"
                        style={{ 
                          backgroundColor: software.status === 'connected' ? colors.successGreen : colors.warningOrange 
                        }}
                      />
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </>
        )}

        {/* Tasks Tab */}
        {activeTab === 'tasks' && (
          <TasksPage
            tasks={tasks}
            milestones={milestones}
            onAddTask={addTask}
            onUpdateTask={toggleTaskComplete}
            onDeleteTask={deleteTask}
          />
        )}

        {/* Shots Tab */}
        {activeTab === 'shots' && (
          <ShotList />
        )}
        
        {/* Notes Tab */}
        {activeTab === 'notes' && (
          <div className="rounded-lg p-6 fade-in shadow-lg" style={{ backgroundColor: '#1a1a1a' }}>
            <div className="flex justify-between items-center mb-8">
              <div>
                <h2 className="text-2xl font-bold text-white mb-2">Notes</h2>
                <p className="text-gray-400">Keep track of ideas, reminders and production notes</p>
              </div>
              
              <button 
                className="px-4 py-2 rounded-lg flex items-center hover-scale transition-all shadow"
                style={{ backgroundColor: colors.accent }}
                onClick={() => setShowAddNoteModal(true)}
              >
                <Plus className="h-4 w-4 mr-1" />
                <span>Add Note</span>
              </button>
            </div>
            
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {notes.length === 0 ? (
                <div className="col-span-full text-center text-gray-500 py-12 bg-gray-800 rounded-lg">
                  No notes yet. Add some!
                </div>
              ) : (
                notes.map(note => (
                  <div 
                    key={note.id} 
                    className="p-4 rounded-lg bg-gray-800 hover-glow transition-all shadow"
                    style={{ borderLeft: `3px solid ${colors.accent}` }}
                  >
                    <div className="flex justify-between items-start mb-3">
                      <div 
                        className="cursor-pointer flex items-center group"
                        onClick={() => toggleNoteComplete(note.id)}
                      >
                        {note.completed ? 
                          <div className="h-5 w-5 rounded-full bg-green-500 flex items-center justify-center mr-2 transition-all group-hover:scale-110">
                            <Check className="h-3 w-3 text-white" />
                          </div> : 
                          <div className="h-5 w-5 rounded-full border border-gray-500 hover:border-white mr-2 transition-all group-hover:scale-110" />
                        }
                        <span className="text-sm text-gray-400">
                          {note.createdAt ? new Date(note.createdAt).toLocaleDateString() : 'No date'}
                        </span>
                      </div>
                      <button 
                        className="p-1 rounded-full hover:bg-gray-700 transition-all"
                        onClick={() => deleteNote(note.id)}
                      >
                        <Trash2 className="h-4 w-4 text-gray-500 hover:text-red-400" />
                      </button>
                    </div>
                    <p className={`${note.completed ? 'text-gray-400 line-through' : 'text-white'}`}>
                      {note.text}
                    </p>
                  </div>
                ))
              )}
            </div>
          </div>
        )}
        
        {/* Concepts Tab */}
        {activeTab === 'concepts' && (
          <ConceptBoard />
        )}
        
        {/* Edit Stat Card Modal */}
        {editingStatCard && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 modal">
            <div className="bg-gray-900 rounded-lg p-6 max-w-md w-full shadow-xl">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-white">Edit {projectStats[editingStatCard].label}</h3>
                <button 
                  className="text-gray-400 hover:text-white transition-all"
                  onClick={() => setEditingStatCard(null)}
                >
                  <XCircle className="h-5 w-5" />
                </button>
              </div>
              
              <div className="space-y-4">
                <div>
                  <label className="block text-gray-400 mb-1">Label</label>
                  <input 
                    type="text"
                    value={projectStats[editingStatCard].label}
                    onChange={(e) => setProjectStats(prev => ({
                      ...prev,
                      [editingStatCard]: {
                        ...prev[editingStatCard],
                        label: e.target.value
                      }
                    }))}
                    className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white"
                  />
                </div>
                
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-gray-400 mb-1">Total</label>
                    <input 
                      type="number"
                      value={projectStats[editingStatCard].total}
                      onChange={(e) => setProjectStats(prev => ({
                        ...prev,
                        [editingStatCard]: {
                          ...prev[editingStatCard],
                          total: parseInt(e.target.value) || 0
                        }
                      }))}
                      className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white"
                    />
                  </div>
                  
                  <div>
                    <label className="block text-gray-400 mb-1">Completed</label>
                    <input 
                      type="number"
                      value={projectStats[editingStatCard].completed}
                      onChange={(e) => setProjectStats(prev => ({
                        ...prev,
                        [editingStatCard]: {
                          ...prev[editingStatCard],
                          completed: parseInt(e.target.value) || 0
                        }
                      }))}
                      className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white"
                    />
                  </div>
                </div>
                
                <div className="flex justify-end gap-3 pt-4">
                  <button 
                    className="px-4 py-2 rounded-lg border border-gray-700 text-gray-400 hover-scale transition-all"
                    onClick={() => setEditingStatCard(null)}
                  >
                    Cancel
                  </button>
                  <button 
                    className="px-4 py-2 rounded-lg text-white hover-scale transition-all"
                    style={{ backgroundColor: colors.accent }}
                    onClick={() => setEditingStatCard(null)}
                  >
                    Save Changes
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
        
        {/* Add Note Modal */}
        {showAddNoteModal && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 modal">
            <div className="bg-gray-900 rounded-lg p-6 max-w-md w-full shadow-xl">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-white">Add New Note</h3>
                <button 
                  className="text-gray-400 hover:text-white transition-all"
                  onClick={() => setShowAddNoteModal(false)}
                >
                  <XCircle className="h-5 w-5" />
                </button>
              </div>
              
              <div className="space-y-4">
                <div>
                  <label className="block text-gray-400 mb-1">Note</label>
                  <textarea 
                    value={newNote}
                    onChange={(e) => setNewNote(e.target.value)}
                    placeholder="Enter your note..."
                    className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white h-32 resize-none"
                  />
                </div>
                
                <div className="flex justify-end gap-3 pt-4">
                  <button 
                    className="px-4 py-2 rounded-lg border border-gray-700 text-gray-400 hover-scale transition-all"
                    onClick={() => {
                      setNewNote('');
                      setShowAddNoteModal(false);
                    }}
                  >
                    Cancel
                  </button>
                  <button 
                    className="px-4 py-2 rounded-lg text-white hover-scale transition-all"
                    style={{ backgroundColor: colors.accent }}
                    onClick={addNoteHandler}
                    disabled={!newNote.trim()}
                  >
                    Add Note
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default App;
